begin;
select plan(15);
\ir fixtures/captures.sql.inc
set local role cadence_command;
select pg_temp.as_actor(1);
select lives_ok($$select private.write_brand('20000000-0000-4000-8000-000000000001',gen_random_uuid(),null,0,'Synthetic brand','Synthetic audience','Synthetic voice','Synthetic guidance')$$,'owner creates a versioned brand playbook');
select pg_temp.as_actor(3);
select is(jsonb_array_length(private.search_private_library('20000000-0000-4000-8000-000000000001','brands','',null,50,'editorial_reuse')->'items'),0,'unassigned editor cannot read brand playbook');
select throws_ok($$select private.create_private_capture('20000000-0000-4000-8000-000000000001',gen_random_uuid(),pg_temp.brand_id('Synthetic brand'),'unassigned','private body','personal_draft',array['editorial_reuse']::private.source_purpose[],false,true,null)$$,'P0001','SOURCE_ACCESS_DENIED','unassigned editor cannot link a capture to restricted brand');
select throws_ok($$select private.set_brand_assignment('20000000-0000-4000-8000-000000000001',gen_random_uuid(),pg_temp.brand_id('Synthetic brand'),'10000000-0000-4000-8000-000000000003',1,true)$$,'P0001','ACCESS_DENIED','editor cannot self-assign brand access');
select pg_temp.as_actor(1);
select lives_ok($$select private.set_brand_assignment('20000000-0000-4000-8000-000000000001',gen_random_uuid(),pg_temp.brand_id('Synthetic brand'),'10000000-0000-4000-8000-000000000003',1,true)$$,'owner assigns brand to current member');
select throws_ok($$select private.set_brand_assignment('20000000-0000-4000-8000-000000000001',gen_random_uuid(),pg_temp.brand_id('Synthetic brand'),'10000000-0000-4000-8000-000000000008',2,true)$$,'P0001','ACCESS_DENIED','brand assignment rejects foreign-workspace member');
select pg_temp.as_actor(3);
select is(jsonb_array_length(private.search_private_library('20000000-0000-4000-8000-000000000001','brands','',null,50,'editorial_reuse')->'items'),1,'assigned editor reads brand');
select private.create_private_capture('20000000-0000-4000-8000-000000000001',gen_random_uuid(),pg_temp.brand_id('Synthetic brand'),'Synthetic branded private','Synthetic brand secret','personal_draft',array['editorial_reuse','excerpt_release']::private.source_purpose[],false,true,null);
select pg_temp.as_actor(1);
select is(jsonb_array_length(private.search_private_library('20000000-0000-4000-8000-000000000001','sources','brand secret',null,50,'editorial_reuse')->'items'),0,'brand owner does not inherit capture access');
select lives_ok($$select private.write_brand('20000000-0000-4000-8000-000000000001',gen_random_uuid(),pg_temp.brand_id('Synthetic brand'),1,'Synthetic brand','New audience','New voice','New guidance')$$,'playbook edits create next version');
select throws_ok($$select private.write_brand('20000000-0000-4000-8000-000000000001',gen_random_uuid(),pg_temp.brand_id('Synthetic brand'),1,'Synthetic brand','stale','stale','stale')$$,'P0001','VERSION_CONFLICT','stale brand edits fail');
select lives_ok($$select private.set_brand_assignment('20000000-0000-4000-8000-000000000001',gen_random_uuid(),pg_temp.brand_id('Synthetic brand'),'10000000-0000-4000-8000-000000000003',2,false)$$,'assignment access version is independent of playbook version');
select pg_temp.as_actor(3);
select throws_ok($$select private.read_source_revision('20000000-0000-4000-8000-000000000001',pg_temp.capture_id('Synthetic branded private'),1,'editorial_reuse')$$,'P0001','SOURCE_ACCESS_DENIED','brand removal immediately blocks branded context');
reset role;
select is((select count(*)::integer from private.brand_playbooks),2,'historical playbook remains immutable');
select ok(not has_column_privilege('cadence_command','private.brands','name','UPDATE'),'direct brand writes cannot bypass versions');
set local role cadence_command;
select pg_temp.as_actor(1);
select set_config('app.actor_id','10000000-0000-4000-8000-000000000003',true);
select is((select count(*)::integer from private.brands),0,'forged command actor cannot read brand rows');
reset role;
select * from finish();
rollback;
